{
  "規則": "整形を gofmt の出力に一致させる",
  "出典": {
    "meta": "go-code-review-comments",
    "引用": "on your code to automatically fix the majority of mechanical style issues."
  },
  "採用範囲": "機械的な整形のみ",
  "検証方法": {
    "道具": ["gofmt", "-l", "."],
    "対象": "出力が空であること"
  }
}

{
  "規則": "Hook は関数の最上位で呼ぶ",
  "出典": {
    "meta": "react-rules-of-hooks",
    "引用": "Instead, always use Hooks at the top level of your React function, before any early returns."
  },
  "採用範囲": "呼び出しの位置のみ",
  "検証方法": {
    "道具": ["eslint", "--rule", "react-hooks/rules-of-hooks: error"],
    "対象": "採用した規則名それぞれ"
  },
  "規則名": ["react-hooks/rules-of-hooks"]
}

{
  "規則": "内側は外側を参照しない",
  "出典": {
    "meta": "clean-architecture-martin",
    "引用": "Nothing in an inner circle can know anything at all about something in an outer circle."
  },
  "採用範囲": "依存の向きのみ。層の名前と並びは採用しない（原典に無い）",
  "検証方法": {
    "道具": ["go", "list", "-deps", "./..."],
    "対象": "層の並び（②が持つ）から組んだ許可辺"
  },
  "向き": "内向き"
}

{
  "規則": "層の並びと、それぞれのパス",
  "出典": { "record": "hexagonal-and-internal-layout" },
  "採用範囲": "この成果物に限る",
  "検証方法": {
    "道具": ["test", "-d"],
    "対象": "層の値それぞれ"
  },
  "並び": ["domain", "usecase", "adapter"],
  "層": {
    "domain":  "internal/domain",
    "usecase": "internal/usecase",
    "adapter": "internal/adapter"
  }
}

{
  "規則": "終了コードの値と意味",
  "出典": {
    "meta": "posix-shell-2.8.2",
    "引用": "If the command is not found, the exit status shall be 127."
  },
  "採用範囲": "原典が規定した値のみ。アプリケーションが返す値は含まない",
  "検証方法": {
    "道具": ["sh", "-c", "<起動>; echo $?"],
    "対象": "値の対応それぞれ"
  },
  "値の対応": {
    "126": "見つかったが、実行できる実体ではなかった",
    "127": "見つからなかった"
  }
}
